WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, INLINE(items) FROM carts) SELECT id, customer_id, created_at, coupon_codes, product_id, qty, price, promo, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY price DESC NULLS FIRST) AS price_dense_rank, ROUND(qty / SUM(qty) OVER (PARTITION BY promo), 4) AS qty_share, ROUND(qty / SUM(qty) OVER (PARTITION BY customer_id), 4) AS qty_share_2, CUME_DIST() OVER (ORDER BY price DESC NULLS LAST) AS price_cume_dist FROM flattened;
